/* First-party brand identities and adjustable seed hypotheses. Saved team work wins. */
(function(root){
 'use strict';
 const registry=root.YOLK_RUNTIME.brandPresets||{brands:[],families:[],fallback:{}},logos=root.YOLK_RUNTIME.brandLogos||{entries:[]};
 const records=new Map(registry.brands.map(b=>[b.brandId,b])),families=new Map(registry.families.map(f=>[f.id,f]));
 const marks=new Map((logos.entries||[]).map(l=>[l.brandId,l]));
 function record(id){return records.get(id)||null}
 function displayName(id,sourceName=''){const b=record(id);return b?tr(b.name.th,b.name.en):sourceName||id}
 function visibleBrands(industry,brands){return brands.filter(b=>b.id!=='unknown').slice(0,industry==='nonbank'?10:Infinity)}
 function familyFor(industry,id,scope){const b=record(id);return families.get(b?.perScopeFamily?.[scope]||registry.fallbackPerScope?.[industry]?.[scope]||b?.defaultFamilyId||registry.fallback[industry])||null}
 function scopeFor(industry,id){return record(id)?.defaultScope||PROFILE_BY_ID[industry].defaultScope}
 function seed(base,industry,id,scope){const family=familyFor(industry,id,scope);return normalizeCriteria({...base,...structuredClone(family?.criteriaOverrides||{}),seedPresetId:family?.id||null,seedVersion:registry.version},{existing:false})}
 function logo(id){const entry=marks.get(id);if(!entry?.localPath||entry.verifiedSquareGraphic!==true)return `<span class="brand-logo-fallback" aria-hidden="true">${uiIcon('store')}</span>`;
  const support=entry.themeSupport||'both',forTheme=theme=>entry.variants?.[theme]||(support==='both'||support===(theme+'Only')?entry:null);
  return `<span class="brand-logo">${['light','dark'].map(theme=>{const asset=forTheme(theme);return asset?`<img class="brand-logo-${theme}" src="${escapeHTML(asset.localPath)}?v=${escapeHTML((asset.sha256||'').slice(0,12))}" alt="" loading="lazy" decoding="async">`:`<span class="brand-logo-fallback-${theme}" aria-hidden="true">${uiIcon('store')}</span>`}).join('')}</span>`;
 }
 function picker(data){const name=displayName(Y.ownBrandId,ownBrandName());return `<button type="button" id="brand-picker" class="brand-picker" data-brand-action="open" aria-haspopup="dialog" ${Y.loading?'disabled':''}>${logo(Y.ownBrandId)}<span>${escapeHTML(name)}</span>${uiIcon('expand_more')}</button><select id="own-brand-select" hidden aria-hidden="true" tabindex="-1">${visibleBrands(Y.industry,data?.brands||[]).map(b=>`<option value="${escapeHTML(b.id)}" ${Y.ownBrandId===b.id?'selected':''}>${escapeHTML(b.name)}</option>`).join('')}</select>`}
 function presetSummary(){const f=familyFor(Y.industry,Y.ownBrandId,Y.supplyScope);if(!f)return '';const b=record(Y.ownBrandId),sources=(f.sourceIds||[]).concat(b?.sourceIds||[]),refs=[...new Set(sources)].map(id=>registry.sourceRefs.find(s=>s.id===id)).filter(Boolean);
  return `<div class="brand-preset-note"><div><strong>${uiIcon('tune')}${tr('เกณฑ์เริ่มต้น: ','Starter: ')}${escapeHTML(tr(f.name.th,f.name.en))}</strong><p>${escapeHTML(tr(f.summary.th,f.summary.en))}</p></div>${Y.route==='criteria'?`<button type="button" class="btn secondary" data-brand-action="try-preset" ${canEdit()?'':'disabled'}>${uiIcon('tune')}${tr('ลองเกณฑ์นี้','Try this preset')}</button>`:`<a href="#criteria">${tr('ดูเกณฑ์และผลบนแผนที่','See criteria & map')} →</a>`}${Y.route==='criteria'?`<details><summary>${uiIcon('fact_check')}${tr('เหตุผลและแหล่งข้อมูล','Rationale & sources')}</summary><p>${tr('ตัวเลขเป็นสมมติฐานของ Yolk ที่ทีมปรับได้ ไม่ใช่เกณฑ์ที่แบรนด์รับรอง ค่าที่เคยบันทึกไว้จะคงเดิม','Numbers are adjustable Yolk hypotheses, not brand-approved rules. Your saved criteria are retained.')}</p>${(Array.isArray(f.hypothesisLimits)?f.hypothesisLimits:[f.hypothesisLimits].filter(Boolean)).map(l=>`<p>${escapeHTML(typeof l==='string'?l:tr(l.th,l.en))}</p>`).join('')}${refs.map(s=>`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.title||s.id)} ${uiIcon('open_in_new')}</a>`).join('')}</details>`:''}</div>`;
 }
 function rows(query=''){const q=query.trim().toLocaleLowerCase(),brands=visibleBrands(Y.industry,root.YOLK_RUNTIME.supplyCache.get(Y.industry)?.brands||[]).filter(b=>[b.name,b.id,record(b.id)?.name.th,record(b.id)?.name.en].join(' ').toLocaleLowerCase().includes(q));
  return brands.map(b=>{const name=displayName(b.id,b.name);return `<button type="button" class="brand-choice" data-brand-action="choose" data-brand-id="${escapeHTML(b.id)}" aria-pressed="${b.id===Y.ownBrandId}">${logo(b.id)}<span><strong>${escapeHTML(name)}</strong>${Y.industry==='nonbank'?`<small>${escapeHTML(b.name)}</small>`:''}${Number.isFinite(b.sourceRowCount)?`<small>${tr('รายการต้นทาง','Source records')} ${b.sourceRowCount.toLocaleString()}</small>`:''}</span>${b.id===Y.ownBrandId?uiIcon('fact_check'):uiIcon('arrow_back')}</button>`}).join('')||`<p>${tr('ไม่พบแบรนด์ที่ค้นหา','No matching brands')}</p>`;
 }
 function open(){let dialog=document.getElementById('brand-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='brand-dialog';dialog.className='brand-dialog';document.body.append(dialog);dialog.addEventListener('close',()=>document.getElementById('brand-picker')?.focus());}
  dialog.innerHTML=`<header><div><h2 id="brand-dialog-title">${tr('เลือกแบรนด์ของเรา','Choose our brand')}</h2><p>${Y.industry==='nonbank'?tr('10 รายแรก ตามจำนวนรายการใน CityMETER','Top 10 by CityMETER source record count'):industryName()}</p></div><button type="button" class="btn secondary icon-only" data-brand-action="close" aria-label="${tr('ปิด','Close')}">${uiIcon('close')}</button></header><label class="brand-search">${uiIcon('search')}<input type="search" id="brand-search" placeholder="${tr('ค้นหาชื่อแบรนด์','Search brands')}" aria-label="${tr('ค้นหาแบรนด์','Search brands')}"></label><div class="brand-choices" id="brand-choices">${rows()}</div><p class="brand-dialog-foot">${tr('โลโก้กราฟิกจากแบรนด์ · ชื่อกำกับทุกแห่ง รายที่ยังไม่มีไฟล์เหมาะสมใช้ไอคอนกลาง','Official compact brand graphics, always paired with names. A neutral icon stands in when a suitable original is unavailable.')}</p>`;
  dialog.setAttribute('aria-labelledby','brand-dialog-title');dialog.showModal();document.getElementById('brand-search').focus();
 }
 document.addEventListener('input',event=>{if(event.target.id==='brand-search')document.getElementById('brand-choices').innerHTML=rows(event.target.value)});
 document.addEventListener('click',async event=>{const button=event.target.closest('[data-brand-action]');if(!button||button.disabled)return;const action=button.dataset.brandAction;
  if(action==='open')open();else if(action==='close')document.getElementById('brand-dialog')?.close();
  else if(action==='choose'){const id=button.dataset.brandId;document.getElementById('brand-dialog')?.close();if(id===Y.ownBrandId)return;await selectIndustryContext(Y.industry,id);document.getElementById('brand-picker')?.focus();}
  else if(action==='try-preset'){if(!canEdit())return;draft=seed(presetCriteria(Y.industry),Y.industry,Y.ownBrandId,Y.supplyScope);draft.version=Y.criteria.version;draftBase=Y.criteria.version;stashContext();render();notify(tr('โหลดเกณฑ์ให้ลองแล้ว ดูผลบนแผนที่ก่อนบันทึกใช้ทั้งทีม','Preset ready to try. Review the map before applying it to the team.'));}
 });
 root.YolkBrands=Object.freeze({record,displayName,visibleBrands,familyFor,scopeFor,seed,logo,picker,presetSummary,version:registry.version});
})(window);
